SCH = []

SCH.append(dict(
 id='BK', name='Richard Bauckham', dates='n. 1946', role='Biblista británico (St Andrews; Ridley Hall, Cambridge). Autor de <i>Jesus and the God of Israel</i> (2008), donde defiende que el Nuevo Testamento incluye a Jesús en la «identidad divina» única de YHWH',
 why='El académico que más ha desarrollado la tesis de que la cristología más antigua ya incluía a Jesús en la identidad del Dios único de Israel',
 quotes=[
  ('F', 'Cuando los primeros cristianos adoraban a Jesús, no lo veían como un objeto de adoración alternativo o distinto junto a Dios. Incluían a Jesús en su adoración de Dios, como Pablo incluyó a Jesús en el Shemá. [[k:La adoración de Jesús no infringía el monoteísmo judío, porque el propio Jesús pertenecía a la identidad única del único Dios.]]', 'p. 13'),
  ('F', 'Pablo nunca o casi nunca usa la palabra «Dios» de Jesús, pero la palabra «dios» es bastante ambigua y podría entenderse como que Jesús era un segundo dios. [[k:Es mucho más significativo que Pablo pueda tomar textos que se refieren a YHWH como referencias a Jesús.]]', 'p. 13'),
  ('F', 'Pablo debe de querer decir que Jesucristo no era un ayudante creado de Dios, sino que [[k:pertenecía él mismo eternamente a la identidad única del único Dios.]]', 'p. 12 (sobre el papel de Jesús en la creación)'),
 ],
 images=[(PG+'bauckham_p13_f.png', 'Georgetown 2018, p. 13 (PDF p. 38 de 55). Subrayado mío.'), (PG+'bauckham_p12_f.png', 'p. 12 (PDF p. 37). Subrayado mío.')],
 covers=[CV+'J4/covers/monotheism_complexities_2018_ol.jpg', CV+'J4/covers/bauckham_jesus_god_israel_ol.jpg'],
 works=[('Capítulo «Complexities Surrounding God’s Oneness in Biblical Monotheism» (pp. 7-18)', 'En L. Mosher y D. Marshall (eds.), <i>Monotheism and Its Complexities: Christian and Muslim Perspectives</i>, Georgetown University Press, 2018 (Building Bridges Seminar, 2016)', 'PDF abierto de la editorial, alojado por el Berkley Center: s3.amazonaws.com/berkley-center/180601MosherMarshall…pdf', 'VERIFICADO: página real vista y leída (PDF p. = impresa + 25)')],
 clar='Bauckham no dice aquí que <b>el Jesús histórico</b> pronunciara «soy YHWH»: dice que <b>los primeros cristianos</b> (Pablo, los Evangelios) incluyeron a Jesús en la identidad del único Dios, y que lo hicieron desde el principio. Es una respuesta al argumento del vídeo sobre los títulos: lo decisivo no es la palabra «Dios» sino que a Jesús se le aplican textos de YHWH.',
 ojo='En este capítulo la única referencia a la voz del propio Jesús es que llamaba <i>Abba</i> a Dios (p. 17). Bauckham reconoce que «Dios» se aplica a Jesús «solo muy ocasionalmente» (p. 10) y una vez en Juan fuera del Prólogo (20:28, p. 15): el vídeo puede citarlo. Su libro <i>Jesus and the God of Israel</i> (Eerdmans, 2008) <b>no pude leerlo</b> (préstamo digital; Google Books bloqueado): las frases de reseñas que lo citan («la cristología más temprana ya era la más alta», p. 19, según Pitre) están en PI.',
))

SCH.append(dict(
 id='BR', name='Raymond E. Brown', dates='1928-1998', role='Sacerdote católico (sulpiciano) y biblista, Union Theological Seminary (Nueva York); entre los más respetados del siglo XX. Es el que el vídeo cita dos veces',
 why='El vídeo lo usa para negar que Jesús se llamara Dios; sus propias páginas dicen algo más matizado',
 quotes=[
  ('F', 'Jn 20:28: [[k:este es el ejemplo más claro del Nuevo Testamento del uso de «Dios» para Jesús.]] […] La pregunta que da título a este artículo [«¿Llama el Nuevo Testamento Dios a Jesús?»] [[k:debe responderse afirmativamente. En tres casos claros y en cinco con cierta probabilidad, Jesús es llamado Dios en el Nuevo Testamento.]]', 'p. 565'),
  ('F', '«Jesús es Señor» era evidentemente una fórmula de confesión popular en tiempos del Nuevo Testamento, y [[k:con esta fórmula los cristianos dieron a Jesús el título <i>kyrios</i>, que era la traducción estándar de YHWH en la LXX.]]', 'p. 566'),
  ('C', 'Jesús nunca es llamado Dios en los Evangelios Sinópticos, y un pasaje como Mc 10:18 parecería excluir la posibilidad de que Jesús usara el título de sí mismo. [[a:Incluso el cuarto Evangelio nunca presenta a Jesús diciendo específicamente que es Dios.]]', 'p. 566 (concesión: es la parte que usa el vídeo)'),
 ],
 images=[(PG+'brown_p565_f.png', '<i>Theological Studies</i> 26 (1965), p. 565 (PDF p. 21 de 29). Subrayado mío.'), (PG+'brown_p566_f.png', 'p. 566 (PDF p. 22). Naranja: lo que afirma; azul: lo que concede.')],
 covers=[CV+'J8/covers/brown_christology_1994.jpg'],
 works=[('«Does the New Testament Call Jesus God?»', '<i>Theological Studies</i> 26/4 (1965) 545-573; recogido en <i>Jesus: God and Man</i> (1967)', 'PDF abierto de la revista: theologicalstudies.net/wp-content/uploads/2022/08/26.4.1.pdf', 'VERIFICADO: páginas reales vistas (pp. 564-567)'),
        ('<i>An Introduction to New Testament Christology</i>', 'Paulist Press, 1994; trad. castellana <i>Introducción a la cristología del Nuevo Testamento</i> (Sígueme), p. 84 (la del vídeo)', 'Fragmentos del original inglés (archive.org); la p. 84 castellana, vista en el fotograma del vídeo', 'PARCIAL: la frase del vídeo corresponde a «The title “God” would be truly distinctive; but Jesus never uses it of himself and only once is it given affirmatively to him by someone else in the Gospel narrative»')],
 clar='Brown <b>sí</b> concede lo que el vídeo dice: ni en los Sinópticos ni en el cuarto Evangelio Jesús dice «yo soy Dios», y el título «Dios» para Jesús es tardío (p. 567: «Pablo no usa el título en ninguna epístola anterior al 58»). Pero la pregunta que Brown contesta es <b>otra</b>: si el NT <i>llama</i> Dios a Jesús, y su respuesta es afirmativa; y en la n. 52 (p. 566) dice que Juan «hace explícito lo que estaba implícito en el ministerio de Jesús».',
 ojo='La frase de la p. 84 castellana trata del <b>título</b>, no de la identidad. Brown es sobre todo un testigo de que «no usó el título» no es lo mismo que «no hay pretensión divina». No encontré su artículo «Did Jesus Know He Was God?» (1985) ni el apéndice «Ego eimi» de su comentario a Juan: <b>no los cito</b>.',
))

SCH.append(dict(
 id='WR', wide=True, name='N. T. (Tom) Wright', dates='n. 1948', role='Biblista anglicano (St Andrews), exobispo de Durham. Autor de <i>Jesus and the Victory of God</i> (1996)',
 why='Sostiene que Jesús se entendió a sí mismo como la presencia de YHWH que vuelve a Sión, con lenguaje «cifrado» y gestos simbólicos',
 quotes=[
  ('F', 'Jesús creía que, al hacerlo [asumir el destino de Israel y ir a la cruz], [[k:no solo señalaba o hablaba del regreso de YHWH a Sión, sino que lo estaba encarnando realmente.]]', 'ensayo de 1998 (web)'),
  ('F', '[[k:Y parece que Jesús lo creyó acerca de sí mismo.]] El lenguaje era profundamente cifrado, pero la acción simbólica no lo era. [[k:Venía a Sión, haciendo lo que YHWH había prometido hacer.]] Explicó su acción con acertijos que apuntaban todos en la misma dirección.', 'ensayo de 1998 (web)'),
  ('C', '[[a:No creo que Jesús «supiera que era Dios» en el mismo sentido en que uno sabe que está cansado o contento, que es varón o mujer.]]', 'ensayo de 1998 (web): la precisión que Wright mismo añade'),
 ],
 images=[(PG+'wright_b.png', 'ntwrightpage.com, «Jesus and the Identity of God». Subrayado mío.'), (PG+'wright_a.png', 'Mismo ensayo.'), (PG+'wright_c.png', 'Mismo ensayo. Azul: su cautela.')],
 covers=[CV+'J6/covers/jvg_1996_spck_ol155572.jpg'],
 works=[('«Jesus and the Identity of God»', '<i>Ex Auditu</i> 14 (1998) 42-56; versión en la web del autor (publicada en 2016)', 'ntwrightpage.com/2016/07/12/jesus-and-the-identity-of-god/', 'PARCIAL: texto leído en la página web (sin paginación impresa); captura de la página web')],
 clar='Para Wright la pretensión de Jesús es <b>vocacional y simbólica</b>: Jesús se entiende como quien hace lo que YHWH prometió hacer (volver a Sión, reconstruir el templo, perdonar). Es la respuesta más directa a «¿dónde dice “soy Dios”?»: no lo dice así, pero actúa y habla en clave que sus oyentes entendían.',
 ojo='Wright advierte que ninguno de esos gestos es concluyente por sí solo y niega la versión ingenua («no se dijo: ¡soy la segunda persona de la Trinidad!»). Su libro <i>Jesus and the Victory of God</i> (1996) <b>no pude leerlo</b>; todo viene del ensayo web. El vídeo no cita a Wright.',
))

SCH.append(dict(
 id='HU', wide=True, name='Larry W. Hurtado', dates='1943-2022', role='Biblista canadiense (Edimburgo). Autor de <i>Lord Jesus Christ: Devotion to Jesus in Earliest Christianity</i> (2003). Un testigo clave del culto muy temprano a Jesús, pero cauto sobre lo que dijo Jesús de sí mismo',
 why='Aquí hace falta decir lo que dice y lo que no: afirma la devoción muy temprana a Jesús como divino, y que Jesús no reclamó divinidad en la historia',
 quotes=[
  ('F', 'En estos contextos [escatológicos], las referencias a Jesús como «Señor» probablemente connotaban mucho más que «amo». [[k:Parece, de hecho, que a Jesús se le atribuyó el papel escatológico y los atributos de Yahvé.]]', 'artículo «Christology» (<i>NIDB</i>), PDF p. 8 de 16'),
  ('F', 'En muy pocos casos del Nuevo Testamento se aplica el término <i>theos</i> («dios/Dios») a Jesús. [[k:Los casos inequívocos están en Juan 1:1 y 20:28.]]', 'artículo «Christology» (<i>NIDB</i>), PDF p. 11 de 16'),
  ('C', '[[a:El análisis crítico de las tradiciones históricas no ofrece evidencia de que Jesús mismo afirmara compartir la gloria y el estatus divinos durante su carrera terrenal.]]', 'blog de Hurtado, 9-10-2017'),
 ],
 images=[(PG+'hurtado_p8_f.png', '«Christology» (<i>NIDB</i>), PDF p. 8 (versión del autor; sin página impresa). Subrayado mío.'), (PG+'hurtado_p11_f.png', 'PDF p. 11.'), (PG+'hurtado_blog.png', 'larryhurtado.wordpress.com, 9-10-2017. Azul: su límite.')],
 covers=[CV+'J5/covers/lord_jesus_christ_2003_eerdmans.jpg'],
 works=[('«Christology» (artículo de referencia, <i>New Interpreter’s Dictionary of the Bible</i>)', 'Versión del autor en PDF (University of Edinburgh); año y editorial no figuran en el PDF', 'larryhurtado.wordpress.com/wp-content/uploads/2010/07/christology-nidb.pdf', 'PARCIAL: PDF real, sin paginación impresa confirmada'),
        ('«The Origin of “Divine Christology”?»', 'Larry Hurtado’s Blog, 9-10-2017', 'larryhurtado.wordpress.com/2017/10/09/the-origin-of-divine-christology/', 'VERIFICADO: texto leído en la página web')],
 clar='Hurtado da dos cosas que importan: (1) la devoción a Jesús como divino aparece muy pronto y dentro del monoteísmo judío (en Pitre: «brotó de repente y deprisa, no de forma gradual y tardía»); (2) incluso en el vídeo es útil: «solo una vez» en Juan es inexacto, porque para Hurtado los casos inequívocos son Jn 1:1 y 20:28.',
 ojo='<b>Hurtado no está del lado de «Jesús lo dijo»</b>: dice que el análisis histórico no da evidencia de que Jesús afirmara compartir la gloria divina, y (según su ensayo sobre Juan) que los dichos exaltados de Juan reflejan la voz retrospectiva del evangelista. Concede también que en la mayoría de los usos de dirección en los Evangelios <i>kyrios</i> es «Señor/Sir». Sus libros (<i>Lord Jesus Christ</i>, <i>How on Earth Did Jesus Become a God?</i>) <b>no pude leerlos</b>.',
))

SCH.append(dict(
 id='SC', name='Peter Schäfer', dates='n. 1943', role='Especialista en judaísmo antiguo (Princeton, Freie Universität Berlin); autor de <i>Two Gods in Heaven</i> (Princeton UP, 2020)',
 why='Un historiador del judaísmo (no un apologista cristiano) que sostiene que las premisas cristológicas del Nuevo Testamento están enraizadas en el judaísmo del Segundo Templo',
 quotes=[
  ('F', 'La elevación de Jesús de Nazaret como primogénito antes de toda la creación, el Dios encarnado, Hijo de Dios, Hijo del Hombre, el Mesías: [[k:todas estas premisas cristológicas básicas no son paganas ni otras clases de aberraciones; están enraizadas en el judaísmo del Segundo Templo,]] sin importar su carácter específicamente cristiano.', 'p. 5 (Introducción)'),
  ('C', '[[a:No deseo expresamente entrar en la sofisticada discusión neotestamentaria sobre la divinidad de Jesús y sus raíces en el judaísmo primitivo.]]', 'pp. 8-9 (precisión del propio autor)'),
 ],
 images=[(PG+'schafer_p5_f.png', 'Princeton UP, 2020, p. 5 (PDF p. 7 de 23, muestra de la editorial). Subrayado mío.')],
 covers=[CV+'J7/covers/schafer_two_gods_2020_princeton_cover.jpg'],
 works=[('<i>Two Gods in Heaven: Jewish Concepts of God in Antiquity</i>, Introducción', 'Princeton University Press, 2020; trad. de <i>Zwei Götter im Himmel</i> (C. H. Beck, 2017); ISBN 9780691181325', 'PDF de muestra de la editorial: pup-assets.s3.amazonaws.com/public/onix/images/9780691181325/9780691181325.pdf', 'VERIFICADO: página real vista (muestra de la editorial, con su aviso de derechos)')],
 clar='Schäfer dice que la cristología del Nuevo Testamento no es una invención pagana tardía: sus categorías están en el judaísmo. Es un testigo valioso porque escribe como historiador del judaísmo y no como apologista; y discute la lectura de Daniel 7 de Boyarin (según una reseña de 2012 citada en un blog).',
 ojo='<b>Schäfer no dice que Jesús reclamara nada</b>: habla de las premisas del Nuevo Testamento y renuncia expresamente (pp. 8-9) a la discusión sobre la divinidad de Jesús. Afirma que no ve evidencia de un «Hijo de Dios» como segunda deidad en las fuentes del judaísmo palestinense (p. 11). Sirve para refutar «Nicea lo inventó», no para probar «Jesús lo dijo».',
))

SCH.append(dict(
 id='BO', wide=True, name='Daniel Boyarin', dates='n. 1946', role='Talmudista judío (UC Berkeley). Autor de <i>The Jewish Gospels: The Story of the Jewish Christ</i> (2012)',
 why='Un especialista judío que defiende que la cristología alta de los Evangelios es judía y que ya estaba en Jesús y en los judíos de su entorno',
 quotes=[
  ('F', 'Solo es posible entender el Evangelio si tanto Jesús como los judíos que lo rodeaban sostenían una cristología alta según la cual [[k:la pretensión de ser Mesías era también la pretensión de ser un hombre divino.]]', 'epígrafe del artículo de Pitre (CLJ); obra y página no indicadas allí'),
  ('F', 'Mi respuesta sencilla es que «Hijo del Hombre» estaba en labios de Jesús porque era un judío palestino del siglo I, y [[k:«Hijo del Hombre» era el nombre que esos judíos usaban para su esperado redentor divino-humano]] (¡cristológico!).', '«The Sovereignty of the Son of Man: Reading Mark 2» (2010), p. 354 según el bloguero'),
  ('C', 'El Hijo del Hombre tiene autoridad (obviamente [[a:delegada por Dios]]) para hacer la obra de Dios de perdonar pecados en la tierra.', 'mismo ensayo (2010), pp. 353-362'),
 ],
 images=[(PG+'pitre_top.png', 'Church Life Journal (Notre Dame), artículo de B. Pitre, 4-2-2025: epígrafes de Allison y Boyarin. Subrayado mío.')],
 covers=[CV+'J7/covers/boyarin_jewish_gospels_ol13160811.jpg'],
 works=[('Epígrafe (obra no indicada) y ensayo «The Sovereignty of the Son of Man: Reading Mark 2»', 'D. Boyarin, 2010, capítulo en un volumen colectivo (páginas 353-362 según el bloguero); <i>The Jewish Gospels</i>, The New Press, 2012', 'Epígrafe: artículo de Pitre en churchlifejournal.nd.edu; ensayo: reproducción en vridar.org (blog)', 'PARCIAL: solo texto de segunda mano; no leí el libro ni el capítulo')],
 clar='Boyarin responde a dos puntos del vídeo: el «Hijo del hombre» no es simple modismo («no hay evidencia» de que fuera un circunloquio por «yo», contra Vermes), y la divinidad del Mesías era una categoría judía anterior a Jesús.',
 ojo='<b>Es el testigo menos sólido de esta serie</b>: la cita del epígrafe no lleva obra ni página en el artículo de Pitre y el ensayo lo vi solo en un blog. Boyarin matiza que la autoridad del Hijo del Hombre es «delegada» y limitada «al ámbito humano» (sobre el sábado). Schäfer discute su lectura de Daniel 7.',
))

SCH.append(dict(
 id='PI', wide=True, name='Brant Pitre', dates='', role='Biblista católico (Augustine Institute). Autor de <i>Jesus and Divine Christology</i> (Eerdmans, 2024). Es el último autor que cita el vídeo',
 why='El vídeo usa un párrafo de su artículo como «reconocimiento»; el artículo entero dice lo contrario de lo que el vídeo concluye',
 quotes=[
  ('F', 'La mejor explicación de por qué los primeros seguidores judíos de Jesús creyeron que era divino poco después de su muerte [[k:es que Jesús mismo habló y actuó como si fuera divino durante su vida.]] […] Se puede argumentar con fuerza que el Jesús histórico afirmó ser divino, [[k:pero lo hizo de una manera muy judía,]] con acertijos, preguntas y alusiones a la Escritura.', 'CLJ, 4-2-2025'),
  ('F', 'Un número notable de estudiosos coincide en que los primeros seguidores judíos de Jesús sostenían una cristología «alta». [[k:«La idea de que Jesús es Dios […] fue la visión de los primeros cristianos muy poco después de la muerte de Jesús» (Ehrman). «La cristología más temprana era ya la cristología más alta» (Bauckham). «La devoción a Jesús como divino brotó de repente y deprisa» (Hurtado).]]', 'CLJ, 4-2-2025 (lista de citas de estudiosos)'),
  ('C', 'Para la investigación contemporánea sobre Jesús tomada en su conjunto, la respuesta a la pregunta «¿Afirmó Jesús ser divino?» [[a:es un rotundo no.]]', 'CLJ, 4-2-2025: es el pasaje que enseña el vídeo; Pitre lo presenta como la opinión que va a discutir'),
 ],
 images=[(PG+'pitre_best.png', 'Church Life Journal, 4-2-2025. Subrayado mío (captura de la página web).'), (PG+'pitre_high.png', 'Mismo artículo.'), (PG+'pitre_sum.png', 'Mismo artículo. Azul: el pasaje del vídeo.')],
 covers=[],
 works=[('«Jesus’s Divinity and the Quest for the Historical Jesus»', 'Church Life Journal (McGrath Institute for Church Life, Univ. of Notre Dame), 4-2-2025; adaptación de <i>Jesus and Divine Christology</i>, Eerdmans, 2024 (ISBN 9780802875129)', 'churchlifejournal.nd.edu/articles/jesuss-divinity-and-the-quest-for-the-historical-jesus/', 'VERIFICADO: artículo leído entero en la página web; no obtuve la portada del libro')],
 clar='El «rotundo no» describe el estado de la cuestión; a continuación Pitre expone que los mismos estudiosos admiten una cristología alta muy temprana y que eso plantea un problema («si Jesús nunca se dijo divino, ¿cómo surge?»). Su tesis es la contraria de la que el vídeo le atribuye.',
 ojo='Pitre es parte interesada (católico, defiende su tesis) y su «lo contrario» es una argumentación, no un consenso: él mismo escribe que «hay excepciones» y que en la investigación reciente preguntarlo era una «zona prohibida». Sobre el <i>Handbook</i>: su nota 26 cita dos capítulos sobre las pretensiones mesiánicas de Jesús; el índice incluye Broadhead, «Implicit Christology and the Historical Jesus» (ARCE). No leí esos capítulos.',
))

SCH.append(dict(
 id='BI', wide=True, name='Michael F. Bird y Craig A. Evans', dates='', role='Biblistas evangélicos (Ridley College, Melbourne; Houston Christian University). Coautores de <i>How God Became Jesus</i> (Zondervan, 2014), respuesta a Bart Ehrman',
 why='Defienden que Jesús se identificó como «agente divino» y que la deificación de Jesús tiene sus raíces en sus palabras y obras',
 quotes=[
  ('F', 'Mi objetivo es mostrar que [[k:Jesús se identificó a sí mismo como un agente divino con una autoridad única y una relación única con el Dios de Israel.]]', 'M. Bird, en el extracto de Zondervan, p. 46'),
  ('F', 'Además, en el juicio de Jesús, [[k:lo más probable es que dijera algo en el sentido de que creía ser la figura de Dn 7:13-14 y que estaba legítimamente entronizado junto a Dios.]]', 'M. Bird, en el mismo extracto'),
  ('F', 'La deificación de Jesucristo en el Nuevo Testamento, vista sobre todo en las teologías de Pablo y del cuarto evangelista, [[k:tiene sus raíces en las palabras y actividades del Jesús histórico.]]', 'C. Evans, citado por Bird en el extracto (pp. 45-46, 70)'),
 ],
 images=[(PG+'bird_b.png', 'zondervanacademic.com, «Did Jesus Claim He Was God? An Excerpt from <i>How God Became Jesus</i>». Subrayado mío.'), (PG+'bird_a.png', 'Mismo extracto.')],
 covers=[CV+'J9/covers/ol-7275689-L.jpg'],
 works=[('<i>How God Became Jesus: The Real Origins of Belief in Jesus’ Divine Nature. A Response to Bart D. Ehrman</i>', 'M. F. Bird, C. A. Evans, S. J. Gathercole, C. E. Hill y C. Tilling; Zondervan, 2014', 'Extracto publicado por la editorial: zondervanacademic.com/blog/did-jesus-claim-he-was-god-an-excerpt-from-how-god-became-jesus', 'VERIFICADO: texto leído en el extracto web; página del libro 46 según el propio extracto')],
 clar='Bird distingue lo que Jesús habría dicho «hablando por Dios de modo inmediato» y lo que el cristianismo posterior dijo («pudo decir más, pero nunca dijo menos»). Evans, citado por él, resume la tesis: la deificación neotestamentaria arranca en Jesús mismo.',
 ojo='Bird <b>matiza</b> («lo más probable», «agente divino») y es una tesis, no un consenso; críticos como Perriman discuten que el Hijo del Hombre se siente en un trono divino. En su blog (Substack) Bird dice que la tesis de Dunn y Casey, según la cual solo en Juan Jesús llega a ser «Dios», es un «mito» ya superado: es su opinión. No pude leer los libros de Evans, Gathercole (<i>The Preexistent Son</i>), Bock ni Witherington.',
))
